import{_ as o,o as a,c as t,a2 as i}from"./chunks/framework.mzJ8I8R4.js";const u=JSON.parse('{"title":"下载和安装","description":"","frontmatter":{},"headers":[],"relativePath":"guide/install.md","filePath":"guide/install.md"}'),l={name:"guide/install.md"};function p(r,e,d,s,n,h){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="下载和安装" tabindex="-1">下载和安装 <a class="header-anchor" href="#下载和安装" aria-label="Permalink to &quot;下载和安装&quot;">​</a></h1><p>NextTodo 有 Android、iOS、macOS 和 Windows App。连接自己的服务器时，也可以在浏览器里使用网页版。下面的下载链接总是最新版。</p><h2 id="android" tabindex="-1">Android <a class="header-anchor" href="#android" aria-label="Permalink to &quot;Android&quot;">​</a></h2><p>要求 Android 8.0 及以上。</p><ol><li>用手机浏览器打开 <a href="https://github.com/JunieXD/NextTodo/releases/latest/download/NextTodo-android.apk" target="_blank" rel="noreferrer">NextTodo-android.apk</a>，下载安装包。</li><li>下载完成后点开它。第一次安装从浏览器下载的应用时，系统会提示不允许安装未知来源的应用：点击“设置”，打开“允许来自此来源的应用”，返回后继续安装。各品牌手机的叫法略有不同。</li><li>打开 NextTodo，<a href="./#modes">选择用法</a>。</li></ol><p>要按时收到截止提醒，打开 App 的“设置 → 提醒和后台”，按提示允许“通知”和“准时提醒”。小米、红米等使用澎湃 OS 的手机，还要点“自启动和省电”一行的“打开设置”，允许自启动，并把省电策略设为“无限制”；要让提醒在屏幕顶部弹出，再进“通知管理”，在“截止提醒”里打开“悬浮通知”。同一页里的“弹窗提醒”打开后，到点在屏幕底部弹出卡片，需要允许“显示在其他应用上层”（澎湃 OS 叫“悬浮窗”）。</p><p>桌面小组件：长按手机桌面的空白处，选择“小组件”，找到 NextTodo，拖到桌面上。小组件显示“接下来”，可以直接勾选完成；点右上角的 + 打开 App 的添加框，键盘随即弹出。没联网时勾选先存下，联网后自动补上。默认是 4×2 的大小，可以拖动边框调整：不到 3 格高时每项占一行、不显示文件夹，以便多放几项；更高时每项两行，第二行写着文件夹。文字大小在 App 的“设置 → 外观”里调。</p><p>另有一个“日程”小组件，按天列出今天起 7 天截止的事项，最前面是已逾期的；重复的事项以后的每一次也列在那天，写着“以后的一次”。它只用来看：点一项打开详情，点标题“日程”打开日历。</p><p>写进系统日历：在“设置 → 提醒和后台”里打开“写进系统日历”并允许读写日历，带截止时间的未完成事项就会出现在手机的日历里，只有日期的是全天日程。默认写进一个只在这台手机上的“NextTodo”日历；也可以在同一行换成 Google、小米等账号的日历，那样日程会随账号同步到云端。日程跟着事项更新，完成或删掉的会从日历里去掉。“NextTodo”日历是只读的；写进账号日历的，在日历里改了或删了，下次会按事项写回来。日程不带提醒，提醒仍由 NextTodo 发出。退出登录或改用服务器时，写进去的日程会删掉。</p><h2 id="ios" tabindex="-1">iOS <a class="header-anchor" href="#ios" aria-label="Permalink to &quot;iOS&quot;">​</a></h2><p>要求 iOS 16.4 及以上（iPhone 8 及以后的机型）。</p><p>NextTodo 不上架 App Store，用 <a href="https://sidestore.io" target="_blank" rel="noreferrer">SideStore</a> 安装：它用你自己的 Apple ID 给 App 签名，不用花钱，也不用越狱。</p><ol><li><p>装好 SideStore：按 SideStore 官网的<a href="https://docs.sidestore.io/docs/installation/prerequisites" target="_blank" rel="noreferrer">安装指南</a>操作，需要用电脑装一次，同时会装上它要用的 LocalDevVPN。之后在 SideStore 里安装、更新和续签 App 时，都要先打开 LocalDevVPN。</p></li><li><p>在 iPhone 上打开 SideStore，进“Sources”（软件源）页，点 +，填入下面的地址并添加：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://github.com/JunieXD/NextTodo/releases/latest/download/sidestore.json</span></span></code></pre></div></li><li><p>在这个软件源里找到 NextTodo，点击安装。</p></li><li><p>打开 NextTodo，<a href="./#modes">选择用法</a>。</p></li></ol><p>用免费 Apple ID 签名的 App 7 天后过期，过期后打不开，但数据还在。SideStore 会在后台自动续签；隔几天打开一次 LocalDevVPN 和 SideStore，在“My Apps”页点“Refresh All”最稳妥。免费 Apple ID 同时只能装 3 个这样签名的 App，SideStore 自己算一个。</p><p>截止提醒：第一次设了提醒后，App 会请求发送通知，点“允许”。到点即使没打开 App 也会弹出通知；长按通知可以直接“完成”，或推迟 15 分钟、1 小时、3 小时。点了“不允许”的，到 App 的“设置 → 提醒”里点“允许”，在打开的系统设置里打开“允许通知”。</p><h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h2><p>要求 macOS 14 及以上。</p><ol><li><p>下载安装包，双击打开：</p><ul><li>Apple 芯片（M1 及以后）：<a href="https://github.com/JunieXD/NextTodo/releases/latest/download/NextTodo-macos-arm64.dmg" target="_blank" rel="noreferrer">NextTodo-macos-arm64.dmg</a></li><li>Intel 芯片：<a href="https://github.com/JunieXD/NextTodo/releases/latest/download/NextTodo-macos-x64.dmg" target="_blank" rel="noreferrer">NextTodo-macos-x64.dmg</a></li></ul><p>不知道是哪种的，点屏幕左上角的苹果菜单 → “关于本机”：有“芯片”一行、写着 Apple M1 这类的是 Apple 芯片，有“处理器”一行、写着 Intel 的是 Intel 芯片。</p></li><li><p>把窗口里的 NextTodo 拖进“应用程序”文件夹。不要直接在这个窗口里打开它，否则以后无法安装命令行。</p></li><li><p>打开“应用程序”文件夹，双击 NextTodo。第一次打开时，系统会提示无法验证开发者：</p><ol><li>点击“完成”关掉提示。</li><li>打开“系统设置 → 隐私与安全性”，在页面下方找到关于 NextTodo 的提示，点击“仍要打开”，按提示输入登录密码。</li><li>之后可以正常打开，不会再提示。</li></ol><p>出现提示是因为 NextTodo 没有向苹果付费做签名公证，不代表它有问题。</p></li><li><p><a href="./#modes">选择用法</a>。</p></li></ol><p>关掉窗口后，NextTodo 仍在菜单栏里，继续同步和提醒。点菜单栏的图标弹出小窗：看接下来要做的事、切换文件夹、勾选完成、快速添加，不用打开主窗口；右键图标选“退出”才会退出。还可以在“设置 → 提醒和后台”里设一个小窗快捷键，在任何应用里按下就能弹出小窗。要开机时自动运行，在“设置 → 提醒和后台”里开启“登录时启动”。觉得字太大或太小，在“设置 → 外观”里给主窗口和小窗分别选“界面大小”。</p><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><p>要求 Windows 10 或 11，x64。</p><ol><li>下载 <a href="https://github.com/JunieXD/NextTodo/releases/latest/download/NextTodo-windows-x64-setup.exe" target="_blank" rel="noreferrer">NextTodo-windows-x64-setup.exe</a>，双击运行。</li><li>出现“Windows 已保护你的电脑”时，点击“更多信息”，再点击“仍要运行”。原因和 macOS 一样，安装程序没有付费签名。</li><li>按提示完成安装。安装程序只装给当前用户，不需要管理员权限；系统缺少 WebView2 时会自动下载。</li><li><a href="./#modes">选择用法</a>。</li></ol><p>关掉窗口后，NextTodo 仍在任务栏右下角的托盘里，继续同步和提醒。点托盘图标弹出小窗，用法和 macOS 一样；右键托盘图标选“退出”才会退出。小窗快捷键同样在“设置 → 提醒和后台”里设。要开机时自动运行，在“设置 → 提醒和后台”里开启“登录时启动”。界面大小同样在“设置 → 外观”里调。</p><h2 id="网页版" tabindex="-1">网页版 <a class="header-anchor" href="#网页版" aria-label="Permalink to &quot;网页版&quot;">​</a></h2><p>只在连接服务器时可用：用浏览器打开服务器的地址，登录即可。</p><p>网页版可以安装成独立的窗口：Chrome 和 Edge 点地址栏右侧的“安装”图标；iPhone 和 iPad 的 Safari 点“分享 → 添加到主屏幕”。网页版不弹出截止提醒，需要提醒的请用 App。</p><h2 id="更新" tabindex="-1">更新 <a class="header-anchor" href="#更新" aria-label="Permalink to &quot;更新&quot;">​</a></h2><p>Android 和电脑上的 App 不用手动更新：</p><ul><li><strong>连接服务器时</strong>：App 从服务器获取更新，服务器升级后随之更新。Android 下次打开时生效，需要换安装包时会提示；电脑上在后台下载，提示“重启”后生效。</li><li><strong>在本机使用时</strong>：App 从 GitHub 获取更新，有新版本时同样会提示。</li></ul><p>iOS 的 App 不能自己更新：有新版本时会提示，到 SideStore 的“My Apps”页更新。</p><p>版本号在“设置 → 关于”里查看。点按“App 版本”可以立即检查更新，下方会显示检查结果；连不上服务器或 GitHub 时也会写明。Android 平时只更新界面部分，很少需要换安装包，所以安装包的版本常常比 App 版本旧，两者不同时“App 版本”下方另写着安装包的版本。</p>',31)])])}const m=o(l,[["render",p]]);export{u as __pageData,m as default};
